<template>
  <div class="page-ai-tool-generation">
    <h2 class="page-title">{{ t('ai.tools.title') }}</h2>

    <!-- 非企业版：隐藏功能入口，展示升级/403 提示 -->
    <el-card v-if="!checking && !allowed" class="gate-card">
      <el-result
        icon="warning"
        :title="t('ai.tools.gateTitle')"
        :sub-title="t('ai.tools.gateSubtitle')"
      >
        <template #extra>
          <el-button type="primary" @click="$router.push('/settings/license')">
            {{ t('ai.tools.gateAction') }}
          </el-button>
        </template>
      </el-result>
    </el-card>

    <template v-if="allowed">
      <el-card class="generate-card">
        <template #header>
          <span>{{ t('ai.tools.generateCard') }}</span>
        </template>
        <el-form :inline="true" @submit.prevent>
          <el-form-item :label="t('ai.tools.analysisIdLabel')">
            <el-input-number
              v-model="analysisId"
              :min="1"
              placeholder="analysis_id"
              controls-position="right"
            />
          </el-form-item>
          <el-form-item>
            <el-button
              type="primary"
              :loading="generating"
              :disabled="!analysisId"
              @click="onGenerate"
            >
              {{ t('ai.tools.generateButton') }}
            </el-button>
          </el-form-item>
        </el-form>
        <div class="form-hint">
          {{ t('ai.tools.generateHintPrefix') }}<b>{{ t('ai.tools.generateHintBold') }}</b>{{ t('ai.tools.generateHintSuffix') }}
        </div>
      </el-card>

      <el-card class="list-card">
        <template #header>
          <div class="list-header">
            <span>{{ t('ai.tools.listTitle') }}</span>
            <div class="filters">
              <el-select
                v-model="filterStatus"
                :placeholder="t('common.status')"
                clearable
                style="width: 140px"
                @change="onFilterChange"
              >
                <el-option :label="t('common.pendingReview')" value="pending_review" />
                <el-option :label="t('common.approved')" value="approved" />
                <el-option :label="t('common.rejected')" value="rejected" />
                <el-option :label="t('ai.statusDeprecated')" value="deprecated" />
              </el-select>
              <el-select
                v-model="filterRisk"
                :placeholder="t('common.risk')"
                clearable
                style="width: 120px"
                @change="onFilterChange"
              >
                <el-option :label="t('common.low')" value="low" />
                <el-option :label="t('common.medium')" value="medium" />
                <el-option :label="t('common.high')" value="high" />
              </el-select>
              <el-button @click="loadList">{{ t('common.refresh') }}</el-button>
            </div>
          </div>
        </template>

        <el-table v-loading="loading" :data="tools" stripe>
          <el-table-column prop="id" label="ID" width="70" />
          <el-table-column prop="name" :label="t('common.name')" min-width="160" show-overflow-tooltip />
          <el-table-column prop="language" :label="t('ai.tools.language')" width="90" />
          <el-table-column :label="t('common.status')" width="110">
            <template #default="{ row }">
              <el-tag :type="statusTagType(row.status)" size="small">
                {{ statusText(row.status) }}
              </el-tag>
            </template>
          </el-table-column>
          <el-table-column :label="t('common.risk')" width="90">
            <template #default="{ row }">
              <el-tag :type="riskTagType(row.risk_level)" size="small">
                {{ riskText(row.risk_level) }}
              </el-tag>
            </template>
          </el-table-column>
          <el-table-column prop="source_incident_id" :label="t('ai.tools.sourceIncident')" width="100" />
          <el-table-column prop="generated_by_ai" :label="t('ai.tools.model')" min-width="140" show-overflow-tooltip />
          <el-table-column prop="created_at" :label="t('common.createdAt')" min-width="170" />
          <el-table-column :label="t('common.actions')" width="120" fixed="right">
            <template #default="{ row }">
              <el-button link type="primary" size="small" @click="openDetail(row.id)">
                {{ t('ai.tools.detailReview') }}
              </el-button>
            </template>
          </el-table-column>
        </el-table>

        <div class="pagination">
          <el-pagination
            v-model:current-page="page"
            v-model:page-size="pageSize"
            :total="total"
            :page-sizes="[10, 20, 50]"
            layout="total, sizes, prev, pager, next"
            @current-change="loadList"
            @size-change="onSizeChange"
          />
        </div>
      </el-card>
    </template>

    <!-- 详情抽屉 -->
    <el-drawer
      v-model="drawerVisible"
      :title="detail ? t('ai.tools.detailTitle', { id: detail.id }) : t('ai.tools.detailTitleEmpty')"
      size="60%"
      :destroy-on-close="true"
    >
      <div v-loading="detailLoading">
        <template v-if="detail">
          <el-descriptions :column="2" border>
            <el-descriptions-item :label="t('common.name')">{{ detail.name }}</el-descriptions-item>
            <el-descriptions-item :label="t('ai.tools.language')">{{ detail.language }}</el-descriptions-item>
            <el-descriptions-item :label="t('common.status')">
              <el-tag :type="statusTagType(detail.status)" size="small">
                {{ statusText(detail.status) }}
              </el-tag>
            </el-descriptions-item>
            <el-descriptions-item :label="t('heal.riskLevel')">
              <el-tag :type="riskTagType(detail.risk_level)" size="small">
                {{ riskText(detail.risk_level) }}
              </el-tag>
            </el-descriptions-item>
            <el-descriptions-item :label="t('ai.tools.sourceIncident')">
              {{ detail.source_incident_id ?? '-' }}
            </el-descriptions-item>
            <el-descriptions-item :label="t('ai.tools.sourceAnalysis')">
              {{ detail.source_analysis_id ?? '-' }}
            </el-descriptions-item>
            <el-descriptions-item :label="t('ai.tools.contentHash')" :span="2">
              <code>{{ detail.content_hash }}</code>
            </el-descriptions-item>
            <el-descriptions-item :label="t('ai.tools.linkedAction')" :span="2">
              {{ detail.linked_action_id ?? t('ai.tools.notInActionLibrary') }}
            </el-descriptions-item>
            <el-descriptions-item :label="t('common.description')" :span="2">
              {{ detail.description ?? '-' }}
            </el-descriptions-item>
          </el-descriptions>

          <h4 class="section-title">{{ t('common.scriptContent') }}</h4>
          <pre class="code-block">{{ detail.content }}</pre>

          <h4 class="section-title">{{ t('ai.tools.scanTitle') }}</h4>
          <el-alert
            :type="detail.scan.passed ? 'success' : 'error'"
            :closable="false"
            :title="detail.scan.passed ? t('ai.tools.scanPassed') : t('ai.tools.scanFailed')"
            :description="detail.scan.reason"
            show-icon
          />
          <el-table
            v-if="detail.scan.findings.length"
            :data="detail.scan.findings"
            size="small"
            class="findings-table"
          >
            <el-table-column prop="line" :label="t('ai.tools.findingLine')" width="70" />
            <el-table-column prop="category" :label="t('ai.tools.findingCategory')" width="180" />
            <el-table-column prop="severity" :label="t('ai.tools.findingSeverity')" width="90">
              <template #default="{ row }">
                <el-tag :type="row.severity === 'block' ? 'danger' : 'warning'" size="small">
                  {{ row.severity }}
                </el-tag>
              </template>
            </el-table-column>
            <el-table-column prop="reason" :label="t('ai.tools.findingReason')" min-width="220" show-overflow-tooltip />
            <el-table-column prop="snippet" :label="t('ai.tools.findingSnippet')" min-width="200" show-overflow-tooltip />
          </el-table>
          <div v-if="detail.scan.static_scan_limited" class="form-hint">
            {{ t('ai.tools.scanLimitedHint') }}
          </div>

          <h4 class="section-title">{{ t('ai.tools.sandboxTitle') }}</h4>
          <div v-if="testResult">
            <el-alert
              :type="testResult.passed ? 'success' : 'warning'"
              :closable="false"
              show-icon
              :title="testResult.passed ? t('ai.tools.sandboxPassed') : t('ai.tools.sandboxFailed')"
              :description="testResult.message"
            />
            <el-descriptions :column="2" border size="small" class="test-meta">
              <el-descriptions-item label="exit_code">{{ testResult.exit_code }}</el-descriptions-item>
              <el-descriptions-item label="timed_out">{{ testResult.timed_out }}</el-descriptions-item>
              <el-descriptions-item label="stdout" :span="2">
                <pre class="io-block">{{ testResult.stdout || t('ai.tools.emptyOutput') }}</pre>
              </el-descriptions-item>
              <el-descriptions-item label="stderr" :span="2">
                <pre class="io-block">{{ testResult.stderr || t('ai.tools.emptyOutput') }}</pre>
              </el-descriptions-item>
            </el-descriptions>
          </div>

          <div class="actions">
            <el-button :loading="testing" @click="onTest">{{ t('ai.tools.runSandboxTest') }}</el-button>
            <el-button
              type="success"
              :loading="actionLoading"
              :disabled="detail.status !== 'pending_review'"
              @click="onApprove"
            >
              {{ t('ai.tools.approveButton') }}
            </el-button>
            <el-button
              type="danger"
              :loading="actionLoading"
              :disabled="detail.status !== 'pending_review'"
              @click="onReject"
            >
              {{ t('common.reject') }}
            </el-button>
          </div>
        </template>
      </div>
    </el-drawer>
  </div>
</template>

<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { ElMessage, ElMessageBox } from 'element-plus'
import {
  approveTool,
  generateTool,
  getTool,
  listTools,
  rejectTool,
  testTool,
  type AIGeneratedToolDetail,
  type AIGeneratedToolListItem,
  type AIToolStatus,
  type RiskLevel,
  type SandboxResult,
} from '@/api/aiTools'
import { getLicenseFeatures } from '@/api/license'
import { showError } from '@/utils/error'

const { t } = useI18n()

const checking = ref(true)
const allowed = ref(false)

const tools = ref<AIGeneratedToolListItem[]>([])
const total = ref(0)
const page = ref(1)
const pageSize = ref(20)
const loading = ref(false)
const filterStatus = ref<AIToolStatus | ''>('')
const filterRisk = ref<RiskLevel | ''>('')

const analysisId = ref<number | null>(null)
const generating = ref(false)

const drawerVisible = ref(false)
const detail = ref<AIGeneratedToolDetail | null>(null)
const detailLoading = ref(false)
const testResult = ref<SandboxResult | null>(null)
const testing = ref(false)
const actionLoading = ref(false)

function statusText(s: AIToolStatus): string {
  const map: Record<AIToolStatus, string> = {
    pending_review: t('common.pendingReview'),
    approved: t('common.approved'),
    rejected: t('common.rejected'),
    deprecated: t('ai.statusDeprecated'),
  }
  return map[s] || s
}

function statusTagType(
  s: AIToolStatus
): 'info' | 'success' | 'warning' | 'danger' {
  if (s === 'approved') return 'success'
  if (s === 'rejected') return 'danger'
  if (s === 'deprecated') return 'info'
  return 'warning'
}

function riskText(r: RiskLevel): string {
  const map: Record<RiskLevel, string> = {
    low: t('common.low'),
    medium: t('common.medium'),
    high: t('common.high'),
  }
  return map[r] || r
}

function riskTagType(r: RiskLevel): 'info' | 'success' | 'warning' | 'danger' {
  if (r === 'high') return 'danger'
  if (r === 'medium') return 'warning'
  return 'success'
}

async function loadLicense() {
  checking.value = true
  try {
    const data = await getLicenseFeatures()
    const feature = data.features?.['ai_custom_tool']
    allowed.value = data.edition === 'enterprise' || feature === true
  } catch (error) {
    // 读取失败时按未解锁处理（fail-closed）
    allowed.value = false
  } finally {
    checking.value = false
  }
}

async function loadList() {
  loading.value = true
  try {
    const data = await listTools({
      status: filterStatus.value || undefined,
      risk_level: filterRisk.value || undefined,
      page: page.value,
      page_size: pageSize.value,
    })
    tools.value = data.items
    total.value = data.total
  } catch (error) {
    showError(error, t('ai.tools.loadFailed'))
  } finally {
    loading.value = false
  }
}

function onFilterChange() {
  page.value = 1
  loadList()
}

function onSizeChange() {
  page.value = 1
  loadList()
}

async function onGenerate() {
  if (!analysisId.value) return
  generating.value = true
  try {
    const created = await generateTool({ analysis_id: analysisId.value })
    if (created.status === 'rejected') {
      ElMessage.warning(t('ai.tools.generateRejected'))
    } else {
      ElMessage.success(t('ai.tools.generateSuccess'))
    }
    analysisId.value = null
    await loadList()
    detail.value = created
    testResult.value = null
    drawerVisible.value = true
  } catch (error) {
    showError(error, t('ai.tools.generateFailed'))
  } finally {
    generating.value = false
  }
}

async function openDetail(id: number) {
  drawerVisible.value = true
  detailLoading.value = true
  testResult.value = null
  try {
    detail.value = await getTool(id)
  } catch (error) {
    showError(error, t('ai.tools.loadDetailFailed'))
  } finally {
    detailLoading.value = false
  }
}

async function onTest() {
  if (!detail.value) return
  testing.value = true
  try {
    testResult.value = await testTool(detail.value.id)
    if (testResult.value.passed) {
      ElMessage.success(t('ai.tools.sandboxPassed'))
    } else {
      ElMessage.warning(t('ai.tools.sandboxFailedMsg'))
    }
  } catch (error) {
    showError(error, t('ai.tools.sandboxTestFailed'))
  } finally {
    testing.value = false
  }
}

async function onApprove() {
  if (!detail.value) return
  try {
    await ElMessageBox.confirm(
      t('ai.tools.approveConfirmMsg'),
      t('ai.tools.approveConfirmTitle'),
      { type: 'warning' }
    )
  } catch {
    return
  }
  actionLoading.value = true
  try {
    detail.value = await approveTool(detail.value.id)
    ElMessage.success(t('ai.tools.approvedMsg'))
    await loadList()
  } catch (error) {
    showError(error, t('common.approveFailed'))
  } finally {
    actionLoading.value = false
  }
}

async function onReject() {
  if (!detail.value) return
  let reason = ''
  try {
    const { value } = await ElMessageBox.prompt(t('common.rejectPrompt'), t('common.reject'), {
      inputType: 'textarea',
      confirmButtonText: t('ai.tools.confirmReject'),
      cancelButtonText: t('common.cancel'),
    })
    reason = value || ''
  } catch {
    return
  }
  actionLoading.value = true
  try {
    detail.value = await rejectTool(detail.value.id, reason || undefined)
    ElMessage.success(t('common.rejected'))
    await loadList()
  } catch (error) {
    showError(error, t('common.rejectFailed'))
  } finally {
    actionLoading.value = false
  }
}

onMounted(async () => {
  await loadLicense()
  if (allowed.value) {
    await loadList()
  }
})
</script>

<style scoped>
