  padding: 20px;
}

.page-title {
  margin: 0 0 20px;
  font-size: 20px;
}

.gate-card,
.generate-card,
.list-card {
  margin-bottom: 20px;
}

.form-hint {
  color: var(--el-text-color-secondary);
  font-size: 12px;
  margin-top: 6px;
}

.list-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.filters {
  display: flex;
  gap: 8px;
  align-items: center;
}

.pagination {
  margin-top: 16px;
  display: flex;
  justify-content: flex-end;
}

.section-title {
  margin: 20px 0 10px;
  font-size: 15px;
}

.code-block,
.io-block {
  background: var(--el-fill-color-light);
  border: 1px solid var(--el-border-color-light);
  border-radius: 4px;
  padding: 12px;
