  white-space: pre-wrap;
  word-break: break-all;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 12px;
  margin: 0;
}

.findings-table,
.test-meta {
  margin-top: 10px;
}

.actions {
  margin-top: 24px;
  display: flex;
  gap: 10px;
}
</style>
