import apiClient from './client'
import type { Page } from './page'

export type AIToolLanguage = 'python' | 'shell'
export type AIToolStatus = 'pending_review' | 'approved' | 'rejected' | 'deprecated'
export type RiskLevel = 'low' | 'medium' | 'high'

export interface ScanFinding {
  line: number | null
  category: string
  severity: 'block' | 'warn'
  reason: string
  snippet: string
}

export interface ScanResult {
  passed: boolean
  risk_level: RiskLevel
  findings: ScanFinding[]
  static_scan_limited: boolean
  reason: string
}

export interface SandboxResult {
  passed: boolean
  success: boolean
  exit_code: number
  stdout: string
  stderr: string
  message: string
  timed_out: boolean
  error: string | null
}

export interface AIGeneratedToolListItem {
  id: number
  name: string
  description: string | null
  language: AIToolLanguage
  content_hash: string
  source_incident_id: number | null
  source_analysis_id: number | null
  generated_by_ai: string
  generated_at: string
  risk_level: RiskLevel
  status: AIToolStatus
  approved_by: number | null
  approved_at: string | null
  linked_action_id: string | null
  created_at: string
  updated_at: string
}

export interface AIGeneratedToolDetail extends AIGeneratedToolListItem {
  content: string
  scan: ScanResult
}

export interface GenerateRequest {
  analysis_id: number
}

export interface ListParams {
  status?: AIToolStatus
  risk_level?: RiskLevel
  page?: number
  page_size?: number
}

export async function generateTool(
  data: GenerateRequest
): Promise<AIGeneratedToolDetail> {
  // AI 工具生成需等待 LLM 响应，可能耗时数十秒，单独放宽到 120s（不影响全局 30s 默认）
  const response = await apiClient.post<AIGeneratedToolDetail>(
    '/v1/ai/tools/generate',
    data,
    { timeout: 120000 }
  )
  return response.data
}

export async function listTools(
  params: ListParams = {}
): Promise<Page<AIGeneratedToolListItem>> {
  const response = await apiClient.get<Page<AIGeneratedToolListItem>>(
    '/v1/ai/tools',
    { params }
  )
  return response.data
}

export async function getTool(id: number): Promise<AIGeneratedToolDetail> {
  const response = await apiClient.get<AIGeneratedToolDetail>(
    `/v1/ai/tools/${id}`
  )
  return response.data
}

export async function approveTool(id: number): Promise<AIGeneratedToolDetail> {
  const response = await apiClient.post<AIGeneratedToolDetail>(
    `/v1/ai/tools/${id}/approve`
  )
  return response.data
}

export async function rejectTool(
  id: number,
  reason?: string
): Promise<AIGeneratedToolDetail> {
  const response = await apiClient.post<AIGeneratedToolDetail>(
    `/v1/ai/tools/${id}/reject`,
    { reason: reason ?? null }
  )
  return response.data
}

export async function testTool(id: number): Promise<SandboxResult> {
  const response = await apiClient.post<SandboxResult>(
    `/v1/ai/tools/${id}/test`
  )
  return response.data
}
